52	    @NotEmpty
53	    private String city;
54	
55	    @Column(name = "postcode")
56	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
57	    private String postcode;
58	
59	    @Column(name = "telephone")
60	    @NotEmpty
61	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
62	    private String telephone;
