65	    private String email;
66	
67	    @Column(name = "registration_date")
68	    private LocalDate registrationDate;
69	
70	    @Column(name = "birth_date")
71	    private LocalDate birthDate;
72	
73	    @Column(name = "customer_code")
74	    private String customerCode;
75	
76	    @Column(name = "household_id")
77	    private String householdId;
78	
79	    @Column(name = "identity_key")
80	    private String identityKey;
81	
82	    @Column(name = "namesake_count")
83	    private Integer namesakeCount;
84	
85	    @Column(name = "household_member_count")
86	    private Integer householdMemberCount;
87	
88	    @Column(name = "membership_number")
89	    private String membershipNumber;
90	
91	    @Column(name = "possible_duplicate")
92	    private Boolean possibleDuplicate;
93	
94	    @Column(name = "possible_duplicate_of")
95	    private Integer possibleDuplicateOf;
96	
97	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
98	    private Set<Pet> pets;
