108	    /**
109	     * The owner's salutation, derived on read: the {@link #getTitle() title} and last name separated
110	     * by a single space (e.g. {@code "DR who"}) when a title is present, or just the last name when no
111	     * title was supplied.
112	     */
113	    @Transient
114	    public String getSalutation() {
115	        if (this.title != null && !this.title.isBlank()) {
116	            return this.title + " " + getLastName();
117	        }
118	        return getLastName();
119	    }
120	
121	    public String getAddress() {
122	        return this.address;
123	    }
124	
125	    public void setAddress(String address) {
126	        this.address = address;
127	    }
128	
129	    public String getAddressLine1() {
130	        return this.addressLine1;
131	    }
132	
133	    public void setAddressLine1(String addressLine1) {
134	        this.addressLine1 = addressLine1;
135	    }
136	
137	    public String getAddressLine2() {
138	        return this.addressLine2;
139	    }
140	
141	    public void setAddressLine2(String addressLine2) {
142	        this.addressLine2 = addressLine2;
143	    }
144	
145	    public String getCity() {
146	        return this.city;
147	    }
148	
149	    public void setCity(String city) {
150	        this.city = city;
151	    }
