233	    public String getMembershipNumber() {
234	        return this.membershipNumber;
235	    }
236	
237	    public void setMembershipNumber(String membershipNumber) {
238	        this.membershipNumber = membershipNumber;
239	    }
240	
241	    public Boolean getPossibleDuplicate() {
242	        return this.possibleDuplicate;
243	    }
244	
245	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
246	        this.possibleDuplicate = possibleDuplicate;
247	    }
248	
249	    public Integer getPossibleDuplicateOf() {
250	        return this.possibleDuplicateOf;
251	    }
252	
253	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
254	        this.possibleDuplicateOf = possibleDuplicateOf;
255	    }
