257	    /**
258	     * The owner's membership points, derived on read: they start at 0, add 2 when an email is
259	     * present, add 1 when {@link #namesakeCount} is 0, add 2 for a household of 3 or more
260	     * ({@link #householdMemberCount}), and add 3 for tenure over 365 days (whole days from
261	     * {@link #registrationDate} to today).
262	     */
263	    @Transient
264	    public Integer getMembershipPoints() {
265	        return membershipPoints(this.email, this.namesakeCount, this.householdMemberCount,
266	            this.registrationDate);
267	    }
268	
269	    /**
270	     * The owner's numeric membership level, derived on read from {@link #getMembershipPoints()}:
271	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
272	     */
273	    @Transient
274	    public Integer getMembershipLevel() {
275	        return membershipLevel(getMembershipPoints());
276	    }
277	
278	    /** The membership points derived from the given factors: they start at 0, add 2 when
279	     *  {@code email} is present, add 1 when {@code namesakeCount} is 0, add 2 for a household of 3 or
280	     *  more ({@code householdMemberCount}), and add 3 for tenure over 365 days (whole days from
281	     *  {@code registrationDate} to today). */
282	    private static int membershipPoints(String email, Integer namesakeCount,
283	            Integer householdMemberCount, LocalDate registrationDate) {
284	        int points = 0;
285	        if (email != null && !email.isBlank()) {
286	            points += 2;
287	        }
288	        if (namesakeCount != null && namesakeCount == 0) {
289	            points += 1;
290	        }
291	        if (householdMemberCount != null && householdMemberCount >= 3) {
292	            points += 2;
293	        }
294	        if (registrationDate != null
295	                && java.time.temporal.ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
296	            points += 3;
297	        }
298	        return points;
299	    }
300	
301	    /** The numeric membership level (1-4) mapped from membership points: 1 for 0-1 points, 2 for
302	     *  2-3, 3 for 4-5, and 4 for 6 or more. */
303	    private static int membershipLevel(int points) {
304	        if (points >= 6) {
305	            return 4;
306	        }
307	        if (points >= 4) {
308	            return 3;
309	        }
310	        if (points >= 2) {
311	            return 2;
312	        }
313	        return 1;
314	    }
315	
316	    /**
317	     * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
318	     * present, otherwise {@code "PHONE"}.
319	     */
320	    @Transient
321	    public String getContactPreference() {
322	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
323	    }
324	
325	    /**
326	     * The owner's age band, derived on read from the {@link #birthDate} relative to the
327	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
328	     * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
329	     * date to measure against) is available.
330	     */
331	    @Transient
332	    public String getAgeBand() {
333	        if (this.birthDate == null || this.registrationDate == null) {
334	            return null;
335	        }
336	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
337	        if (age < 18) {
338	            return "MINOR";
339	        }
340	        if (age < 65) {
341	            return "ADULT";
342	        }
343	        return "SENIOR";
344	    }
345	
346	    /**
347	     * The single Luhn check digit (0-9) computed over the decimal digits contained in the
348	     * {@link #customerCode}, derived on read.
349	     */
350	    @Transient
351	    public Integer getCheckDigit() {
352	        return luhnCheckDigit(this.customerCode);
353	    }
354	
355	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
356	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
357	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
358	        "NSW", new int[] {2000, 2099},
359	        "VIC", new int[] {3000, 3099},
360	        "QLD", new int[] {4000, 4099});
361	
362	    /**
363	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
364	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
365	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
366	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
367	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
368	     */
369	    @Transient
370	    public String getRegion() {
371	        String byPostcode = regionForPostcode(this.postcode);
372	        if (byPostcode != null) {
373	            return byPostcode;
374	        }
375	        if ("Sydney".equals(this.city)) {
376	            return "NSW";
377	        }
378	        if ("Melbourne".equals(this.city)) {
379	            return "VIC";
380	        }
381	        if ("Brisbane".equals(this.city)) {
382	            return "QLD";
383	        }
384	        return "UNKNOWN";
385	    }
386	
387	    /**
388	     * The owner's locality, derived on read from the region-and-hash {@link #getCustomerCode()
389	     * customer code}: the region segment before the first '-' of the customer code
390	     * ('<REGION>-<HASH8>'). Falls back to the owner's {@link #getRegion() region} when no customer
391	     * code has been assigned yet.
392	     */
393	    @Transient
394	    public String getLocality() {
395	        if (this.customerCode != null) {
396	            int dash = this.customerCode.indexOf('-');
397	            if (dash > 0) {
398	                return this.customerCode.substring(0, dash);
399	            }
400	        }
401	        return getRegion();
402	    }
403	
404	    /** Region -> IANA timezone name, the fixed region-to-timezone table ({@code NSW ->
405	     *  Australia/Sydney}, {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
406	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
407	        "NSW", "Australia/Sydney",
408	        "VIC", "Australia/Melbourne",
409	        "QLD", "Australia/Brisbane");
410	
411	    /**
412	     * The owner's timezone, derived on read as the IANA name for the owner's
413	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table
414	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
415	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region carries no entry in
416	     * the table (e.g. {@code UNKNOWN}).
417	     */
418	    @Transient
419	    public String getTimezone() {
420	        return timezoneForRegion(getLocality());
421	    }
422	
423	    /** The IANA timezone name for {@code region} via the fixed region-to-timezone table, or
424	     *  {@code null} when the region carries no entry ({@code NSW -> Australia/Sydney},
425	     *  {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
426	    public static String timezoneForRegion(String region) {
427	        return REGION_TIMEZONES.get(region);
428	    }
429	
430	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
431	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
432	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
433	    public static int[] postcodeRangeForRegion(String region) {
434	        return REGION_POSTCODE_RANGES.get(region);
435	    }
436	
437	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
438	     *  absent, not a 4-digit value, or in no known range. */
439	    private static String regionForPostcode(String postcode) {
440	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
441	            return null;
442	        }
443	        int value = Integer.parseInt(postcode);
444	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
445	            int[] range = entry.getValue();
446	            if (value >= range[0] && value <= range[1]) {
447	                return entry.getKey();
448	            }
449	        }
450	        return null;
451	    }
452	
453	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
454	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
455	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
456	     *  {@code +1}), so a number matches at most one. */
457	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
458	        "+61", 9, "+1", 10);
459	
460	    /**
461	     * The stored E.164 {@link #telephone} formatted for humans, derived on read: the country code, a
462	     * space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). Falls back
463	     * to the raw value when it is {@code null} or begins with no recognised country code.
464	     */
465	    @Transient
466	    public String getTelephoneDisplay() {
467	        if (this.telephone == null) {
468	            return null;
469	        }
470	        String countryCode = countryCodeOf(this.telephone);
471	        if (countryCode == null) {
472	            return this.telephone;
473	        }
474	        String national = this.telephone.substring(countryCode.length());
475	        StringBuilder grouped = new StringBuilder(countryCode);
476	        for (int i = 0; i < national.length(); i++) {
477	            if (i % 3 == 0) {
478	                grouped.append(' ');
479	            }
480	            grouped.append(national.charAt(i));
481	        }
482	        return grouped.toString();
483	    }
484	
485	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
486	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
487	    public static String countryCodeOf(String telephone) {
488	        if (telephone == null) {
489	            return null;
490	        }
491	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
492	            if (telephone.startsWith(countryCode)) {
493	                return countryCode;
494	            }
495	        }
496	        return null;
497	    }
498	
499	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
500	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
501	     *  {@code +1 => 10}). */
502	    public static Integer nationalNumberLength(String countryCode) {
503	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
504	    }
505	
506	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
507	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
508	     *  digit-free value yields {@code 0}. */
509	    private static int luhnCheckDigit(String value) {
510	        int sum = 0;
511	        boolean doubling = true;
512	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
513	            char c = value.charAt(i);
514	            if (c < '0' || c > '9') {
515	                continue;
516	            }
517	            int digit = c - '0';
518	            if (doubling) {
519	                digit *= 2;
520	                if (digit > 9) {
521	                    digit -= 9;
522	                }
523	            }
524	            sum += digit;
525	            doubling = !doubling;
526	        }
527	        return (10 - (sum % 10)) % 10;
528	    }
529	
530	    protected Set<Pet> getPetsInternal() {
531	        if (this.pets == null) {
532	            this.pets = new HashSet<>();
533	        }
534	        return this.pets;
535	    }
536	
537	    protected void setPetsInternal(Set<Pet> pets) {
538	        this.pets = pets;
539	    }
540	
541	    public List<Pet> getPets() {
542	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
543	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
544	        return Collections.unmodifiableList(sortedPets);
545	    }
546	
547	    public void setPets(List<Pet> pets) {
548	        this.pets = new HashSet<>(pets);
549	    }
550	
551	    public void addPet(Pet pet) {
552	        getPetsInternal().add(pet);
553	        pet.setOwner(this);
554	    }
555	
556	    /**
557	     * Return the Pet with the given name, or null if none found for this Owner.
558	     *
559	     * @param name to test
560	     * @return true if pet name is already in use
561	     */
562	    public Pet getPet(String name) {
563	        return getPet(name, false);
564	    }
565	
566	    /**
567	     * Return the Pet with the given name, or null if none found for this Owner.
568	     *
569	     * @param name to test
570	     * @return true if pet name is already in use
571	     */
572	    public Pet getPet(String name, boolean ignoreNew) {
573	        name = name.toLowerCase();
574	        for (Pet pet : getPetsInternal()) {
575	            if (!ignoreNew || !pet.isNew()) {
576	                String compName = pet.getName();
577	                compName = compName.toLowerCase();
578	                if (compName.equals(name)) {
579	                    return pet;
580	                }
581	            }
582	        }
583	        return null;
584	    }
585	
586	    public Pet getPet(Integer petId) {
587	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
588	    }
589	
590	    @Override
591	    public String toString() {
592	        return new ToStringCreator(this)
593	
594	            .append("id", this.getId())
595	            .append("new", this.isNew())
596	            .append("lastName", this.getLastName())
597	            .append("firstName", this.getFirstName())
598	            .append("address", this.address)
599	            .append("city", this.city)
600	            .append("telephone", this.telephone)
601	            .toString();
602	    }
603	}
