170	    /**
171	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
172	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
173	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
174	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
175	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
176	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
177	     */
178	    private boolean normalizeAndValidateFields(Owner owner) {
179	        if (!normalizeAddressFields(owner)) {
180	            return false;
181	        }
182	        if (owner.getEmail() != null) {
183	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
184	            if (!EMAIL_PATTERN.matcher(email).matches()) {
185	                return false;
186	            }
187	            if (isDisposableEmailDomain(email)) {
188	                return false;
189	            }
190	            owner.setEmail(email);
191	        }
192	        if (!isPostcodeValidForCity(owner)) {
193	            return false;
194	        }
195	        String telephone = normalizeTelephone(owner.getTelephone());
196	        if (telephone == null) {
197	            return false;
198	        }
199	        owner.setTelephone(telephone);
200	        return true;
201	    }
