426	    /**
427	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
428	     * code, membership number, household id, namesake count and household member count. Each is
429	     * derived from the owner's already-normalized fields and the existing owner population, so this
430	     * must run before the owner is saved, while the counts still exclude the owner being created.
431	     *
432	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
433	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
434	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
435	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
436	     */
437	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
438	        owner.setCustomerCode(generateCustomerCode(owner));
439	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
440	        owner.setHouseholdId(householdId(owner));
441	        owner.setNamesakeCount(countNamesakes(owner));
442	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
443	        if (declaredMember) {
444	            owner.setPossibleDuplicate(false);
445	            owner.setPossibleDuplicateOf(null);
446	        } else {
447	            assignPossibleDuplicate(owner);
448	        }
449	    }
450	
451	    /**
452	     * Whether {@code owner} would join an existing household, i.e. some already-registered owner
453	     * resolves to the same {@link #householdId(Owner) householdId} (same last name and postcode).
454	     * Because the household is keyed on (last name, postcode), such a create is a household duplicate
455	     * and is rejected with {@code 409 CONFLICT} unless the request sets {@code sharesHousehold}, in
456	     * which case the owner is created as a declared household member.
457	     */
458	    private boolean hasExistingHousehold(Owner owner) {
459	        return !findHousemates(owner).isEmpty();
460	    }
461	
462	    /**
463	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
464	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's last name
465	     * (compared case-insensitively with collapsed whitespace) and postcode but carries a different
466	     * telephone. Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf}
467	     * to the matching owner's id. Runs before save, against the existing owner population.
468	     */
469	    private void assignPossibleDuplicate(Owner owner) {
470	        Integer matchId = findPossibleDuplicateOf(owner);
471	        owner.setPossibleDuplicate(matchId != null);
472	        owner.setPossibleDuplicateOf(matchId);
473	    }
474	
475	    /**
476	     * The id of an existing owner that shares {@code owner}'s postcode and last name (compared
477	     * case-insensitively with collapsed whitespace) but has a different telephone, or {@code null}
478	     * when there is none. When several match, the lowest id is returned. An owner without a postcode
479	     * never matches.
480	     */
481	    private Integer findPossibleDuplicateOf(Owner owner) {
482	        String postcode = owner.getPostcode();
483	        if (postcode == null) {
484	            return null;
485	        }
486	        String lastName = normalizeHouseholdField(owner.getLastName());
487	        String telephone = owner.getTelephone();
488	        return this.clinicService.findAllOwners().stream()
489	            .filter(existing -> existing.getId() != null
490	                && postcode.equals(existing.getPostcode())
491	                && normalizeHouseholdField(existing.getLastName()).equals(lastName)
492	                && !telephone.equals(existing.getTelephone()))
493	            .map(Owner::getId)
494	            .min(Integer::compareTo)
495	            .orElse(null);
496	    }
497	
498	    /**
499	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
500	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
501	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
502	     * owner's last name (e.g. 'NSW-1A2B3C4D'). The identity is otherwise a pure function of the
503	     * region and the (telephone, last name) pair; only when the computed code collides with an
504	     * existing owner's customer code is it de-duplicated by appending '-<n>' with the smallest
505	     * {@code n} of 2 or more that makes it unique (e.g. 'NSW-1A2B3C4D-2').
506	     */
507	    private String generateCustomerCode(Owner owner) {
508	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
509	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
510	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8);
511	        String base = owner.getRegion() + "-" + hash8;
512	        return deduplicateCustomerCode(base);
513	    }
514	
515	    /**
516	     * De-duplicate a computed customer code against the existing owner population: when {@code base}
517	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
518	     * {@code n} of 2 or more that yields a code no existing owner carries.
519	     */
520	    private String deduplicateCustomerCode(String base) {
521	        Set<String> existing = this.clinicService.findAllOwners().stream()
522	            .map(Owner::getCustomerCode)
523	            .filter(code -> code != null)
524	            .collect(java.util.stream.Collectors.toSet());
525	        if (!existing.contains(base)) {
526	            return base;
527	        }
528	        int n = 2;
529	        while (existing.contains(base + "-" + n)) {
530	            n++;
531	        }
532	        return base + "-" + n;
533	    }
