535	    /**
536	     * The number of existing owners registered in {@code city}, compared case-insensitively
537	     * with collapsed whitespace.
538	     */
539	    private int countOwnersInCity(String city) {
540	        String normalized = normalizeHouseholdField(city);
541	        return (int) this.clinicService.findAllOwners().stream()
542	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
543	            .count();
544	    }
