546	    /**
547	     * The effective registration date to store for a new owner: the date supplied on the request
548	     * when present, otherwise the current server date, in either case rolled forward to a business
549	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
550	     * This single point of resolution is what every registration-date-derived value (the stored
551	     * date, the membership number's year segment, the per-day create-limit) is computed from.
552	     */
553	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
554	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
555	        return toBusinessDay(date);
556	    }
557	
558	    /**
559	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
560	     * following Monday; a weekday is returned unchanged.
561	     */
562	    private static LocalDate toBusinessDay(LocalDate date) {
563	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
564	            date = date.plusDays(1);
565	        }
566	        return date;
567	    }
568	
569	    /**
570	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
571	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
572	     */
573	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
574	        String yy = String.format("%02d", registrationDate.getYear() % 100);
575	        return customerCode + "-M" + yy;
576	    }
577	
578	    /**
579	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
580	     * last name, compared case-insensitively.
581	     */
582	    private int countNamesakes(Owner owner) {
583	        String firstName = normalizeHouseholdField(owner.getFirstName());
584	        String lastName = normalizeHouseholdField(owner.getLastName());
585	        return (int) this.clinicService.findAllOwners().stream()
586	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
587	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
588	            .count();
589	    }
590	
591	    /**
592	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
593	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
594	     * unusually high daily signup volume.
595	     */
596	    private boolean isBulkSignupWarning() {
597	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
598	    }
599	
600	    /** The number of existing owners whose registration date is {@code date}. */
601	    private int countOwnersRegisteredOn(LocalDate date) {
602	        return (int) this.clinicService.findAllOwners().stream()
603	            .filter(existing -> date.equals(existing.getRegistrationDate()))
604	            .count();
605	    }
606	
607	    /**
608	     * The single derived key all duplicate detection flows through, formed from the owner's
609	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
610	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
611	     * id is derived, so the household segment is empty at that point. Because the telephone is part
612	     * of the key, two owners in the same household with different telephones resolve to different
613	     * keys and are both allowed.
614	     */
615	    private static String identityKey(Owner owner) {
616	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
617	        String email = owner.getEmail() == null ? "" : owner.getEmail();
618	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
619	        return telephone + "|" + email + "|" + household;
620	    }
621	
622	    /**
623	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
624	     * duplicate condition: the previously separate telephone, email and household checks are now all
625	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
626	     * trips it is rejected with {@code 409 CONFLICT}.
627	     */
628	    private boolean isDuplicate(Owner owner) {
629	        String key = owner.getIdentityKey();
630	        return this.clinicService.findAllOwners().stream()
631	            .map(Owner::getIdentityKey)
632	            .filter(existing -> existing != null)
633	            .anyMatch(key::equals);
634	    }
