636	    /** Common street-type abbreviations expanded during address normalization. */
637	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
638	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
639	
640	    /**
641	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
642	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
643	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
644	     * string when {@code address} is null or blank after normalization.
645	     */
646	    private static String normalizeAddress(String address) {
647	        if (address == null) {
648	            return "";
649	        }
650	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
651	        if (collapsed.isEmpty()) {
652	            return "";
653	        }
654	        StringBuilder sb = new StringBuilder(collapsed.length());
655	        for (String token : collapsed.split(" ")) {
656	            if (sb.length() > 0) {
657	                sb.append(' ');
658	            }
659	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
660	        }
661	        return sb.toString();
662	    }
663	
664	    /**
665	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
666	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
667	     */
668	    private static String normalizeHouseholdField(String value) {
669	        if (value == null) {
670	            return "";
671	        }
672	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
673	    }
674	
675	    /**
676	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
677	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
678	     * key rather than re-derived from the underlying fields here, so the household is described in one
679	     * place and every household-keyed value stays consistent with it.
680	     */
681	    private List<Owner> findHousemates(Owner owner) {
682	        String householdId = householdId(owner);
683	        return this.clinicService.findAllOwners().stream()
684	            .filter(existing -> householdId(existing).equals(householdId))
685	            .toList();
686	    }
687	
688	    /**
689	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
690	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
691	     */
692	    private int countHouseholdMembers(Owner owner) {
693	        return findHousemates(owner).size() + 1;
694	    }
695	
696	    /**
697	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
698	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
699	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
700	     * string standing in for a missing postcode), so housemates always resolve to the same value
701	     * regardless of registration order, and owners sharing a last name and postcode share it
702	     * automatically.
703	     */
704	    private static String householdId(Owner owner) {
705	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
706	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
707	        return sha256Hex(key).substring(0, 12);
708	    }
709	
710	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
711	    private static String sha256Hex(String input) {
712	        try {
713	            byte[] digest = MessageDigest.getInstance("SHA-256")
714	                .digest(input.getBytes(StandardCharsets.UTF_8));
715	            StringBuilder sb = new StringBuilder(digest.length * 2);
716	            for (byte b : digest) {
717	                sb.append(String.format("%02X", b));
718	            }
719	            return sb.toString();
720	        }
721	        catch (NoSuchAlgorithmException e) {
722	            throw new IllegalStateException("SHA-256 not available", e);
723	        }
724	    }
725	}
